/** What other modules may call in-process: `ctx.use('media')` (or `ctx.tryUse` for an optional dependency). */
export interface MediaPublicApi {
  /** Asset with renditions and status Used by: catalog, offers, sellers, content, advertising, reviews, returns, support, messaging, customers. */
  getAsset(assetId: string): Promise<MediaAsset | null>;
  /** common.MediaRef (id, url, alt, width, height) for embedding in responses; removed files return the placeholder Used by: catalog, offers, sellers, content, advertising, reviews, returns, support, messaging, search, cart, orders, wishlist. */
  refs(assetIds: string[], size?: 'thumb' | 'small' | 'medium' | 'large' | 'zoom'): Promise<common.MediaRef[]>;
  /** Record that a record uses a file. Fails if the asset is not ready, belongs to another owner (ASSET_NOT_OWNED) or the purpose does not fit the usage. Evidence usages extend retainUntil. Used by: catalog, offers, sellers, content, advertising, reviews, returns, support, messaging, warehouse, trust. */
  attach(assetId: string, usage: UsageInput, expectedOwner: MediaOwner): Promise<void>;
  /** Record that a record no longer uses a file (image replaced, draft deleted) Used by: catalog, offers, sellers, content, advertising, reviews, returns, support, messaging. */
  detach(assetId: string, usage: { module: string, kind: string, refId: string }): Promise<void>;
  /** Evaluate an image against category or placement rules; the result is stored on the asset Used by: catalog, advertising, content, sellers. */
  checkImage(assetId: string, rules: ImageRules): Promise<ImageCheckResult>;
  /** Store a file produced by the platform (private) Used by: audit, offers, customers, finance, reports, warehouse, shipping, inventory. */
  storeGeneratedFile(input: { owner: MediaOwner, fileName: string, contentType: string, body: ReadableStream, ttlHours?: number, purpose: 'export' | 'statement' | 'report' | 'correction_report' | 'data_export' | 'label' }): Promise<MediaAsset>;
  /** Signed link for a private file after the caller's module checked access; recorded for sensitive purposes Used by: customers, finance, reports, audit, sellers, returns, support. */
  signedDownload(assetId: string, principal: identity.Principal, reason?: string): Promise<DownloadLink>;
  /** Takedown on behalf of a moderation decision (trust, reviews, catalog) Used by: trust, reviews, catalog, advertising. */
  remove(assetId: string, input: { reason: string, by: common.Actor }): Promise<void>;
}

